namespace YourApp.Services;

public record EquipmentItem(int Id, string Name, string Location, DateOnly LastInspected);

public interface IEquipmentService
{
    Task<List<EquipmentItem>> GetAllAsync();
}

public class EquipmentService : IEquipmentService
{
    public async Task<List<EquipmentItem>> GetAllAsync()
    {
        // Simulate a database or API call
        await Task.Delay(600);

        return new List<EquipmentItem>
        {
            new(1, "Forklift A", "Warehouse 1", new DateOnly(2026, 6, 15)),
            new(2, "Conveyor Belt B", "Warehouse 2", new DateOnly(2026, 5, 20)),
            new(3, "Pallet Jack C", "Warehouse 1", new DateOnly(2026, 7, 01)),
            new(4, "Crane D", "Yard 3", new DateOnly(2026, 4, 10)),
            new(5, "Compressor E", "Maintenance Bay", new DateOnly(2026, 3, 28)),
            new(6, "Welder F", "Shop Floor", new DateOnly(2026, 6, 02)),
            new(7, "Drill Press G", "Shop Floor", new DateOnly(2026, 5, 14)),
            new(8, "Generator H", "Yard 3", new DateOnly(2026, 1, 30)),
        };
    }
}

@page "/inventory"
@using YourApp.Services
@attribute [StreamRendering]
@rendermode InteractiveServer
@inject IEquipmentService EquipmentService

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToString("yyyy-MM-dd")</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? items;

    protected override async Task OnInitializedAsync()
    {
        items = await EquipmentService.GetAllAsync();
    }
}

